esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function: attempt a withdraw of `amount` (no prior deposits assumed)
    function run(uint256 amount) public payable {
        // no assumptions about initial balances; allow any amount
        // record observable before-values
        uint256 beforeContractBal = address(c).balance;

        // call withdraw and capture whether it reverted
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values: recorded balance for this contract can only be observed via a behavior
        // There is no public getter for balances in C (it's private), so observe effect by comparing
        // contract Ether balance change and revert flag. But C has withdraw which on success must
        // reduce recorded balance by amount and transfer amount out. We can observe address(c).balance
        uint256 afterContractBal = address(c).balance;

        // General rule: either withdraw reverted and contract balance unchanged, or withdraw succeeded
        // and contract's Ether balance decreased by at least amount.
        // Additionally, if it succeeded then the decrease is at least amount (the transfer occurred).
        assert(
            (reverted && afterContractBal == beforeContractBal)
            || (!reverted && beforeContractBal >= afterContractBal && beforeContractBal - afterContractBal >= amount)
        );
    }

    receive() external payable {}
}

